"use client";
// @motomation-component
// id: aurora
// name: Aurora
// family: backgrounds
// tier: 4
// deps: react
// what: Curtains of northern light hang across a night sky: a sharp lower hem, fading upward in vertical rays, folding slowly. A small WebGL shader draws it; a CSS poster stands in everywhere else.
// use-when: The subject is the far north, night, cold, observation, polar travel or a planetarium: behind a hero or a single quiet section.
// avoid-when: As a generic "AI glow" background; behind body copy; light themes; pages that already run WebGL.
// reduced-motion: A designed still, not a frozen frame: a long-exposure plate. The curtains settle into three smooth ribbons of the same two colours over a dark ridge, under circular star trails; no canvas is mounted.
// touch: Renders at two-thirds resolution on coarse pointers.
// a11y: Decorative (aria-hidden). Capability probe first (Save-Data, ≤ 2 cores, < 4 GB, no or software WebGL → poster only); DPR ≤ 1.5; paused off screen and in hidden tabs; poster and canvas fill the same absolute box, so no layout shift. Keep `sky` dark: text on top is checked against the sky, and the curtains stay in the upper half.
import { useRef, useState, type CSSProperties } from "react";
import { useReducedMotion, useFinePointer } from "../_lib/motion";
import { useCapability, useGL, program, rgb } from "../_lib/ambient";

type Props = { sky?: string; low?: string; high?: string; speed?: number; className?: string; style?: CSSProperties };
const VS = "attribute vec2 p;void main(){gl_Position=vec4(p,0.,1.);}";
const FS = `precision mediump float;uniform vec2 r;uniform float t;uniform vec3 a,b,sky;
float h(float x){return fract(sin(x*127.1)*43758.5453);}
float n(float x){float i=floor(x),f=fract(x);return mix(h(i),h(i+1.),f*f*(3.-2.*f));}
void main(){vec2 uv=gl_FragCoord.xy/r;float x=uv.x*r.x/r.y;vec3 col=sky*(1.-uv.y*.35);
for(int i=0;i<3;i++){float fi=float(i);
float hem=.48+.13*fi+.07*sin(x*1.1+t*.17+fi*2.1)+.05*n(x*2.6+t*.25+fi*9.);
float d=uv.y-hem;float c=smoothstep(-.015,.0,d)*exp(-d*(5.+fi*2.))*(.55+.45*n(x*14.+t*.6+fi*5.));
c*=.65+.35*sin(x*70.+n(x*3.+t*.4)*8.);
col+=mix(a,b,clamp(d*2.6,0.,1.))*c*(.6-.15*fi);}
gl_FragColor=vec4(col,1.);}`;

// Reduced motion: a long exposure of the same sky. Movement becomes time drawn on the plate (star trails around the
// pole, curtains smoothed into ribbons), so the still reads as its own picture, not the animation stopped.
function AuroraStill({ sky, low, high }: { sky: string; low: string; high: string }) {
  const trails = Array.from({ length: 16 }, (_, i) => { const r = 140 + i * 46, a0 = 0.5 + (i % 5) * 0.21, a1 = a0 + 0.34 + (i % 3) * 0.05;
    return `M${1250 + r * Math.cos(a0)} ${-60 + r * Math.sin(a0)}A${r} ${r} 0 0 1 ${1250 + r * Math.cos(a1)} ${-60 + r * Math.sin(a1)}`; }).join("");
  const ribbon = (y: number, a: number, k: number) => `M0 ${y}C400 ${y - a} 700 ${y + a * k} 1000 ${y - a * 0.4}S1450 ${y + a * 0.5} 1600 ${y - a * 0.2}V${y - 330}H0Z`;
  return (
    <svg viewBox="0 0 1600 1000" preserveAspectRatio="xMidYMid slice" style={box}>
      <defs>
        <linearGradient id="au-s" x1="0" y1="1" x2="0" y2="0"><stop offset="0" stopColor={sky} /><stop offset="1" stopColor="#0b1428" /></linearGradient>
        <linearGradient id="au-r" x1="0" y1="1" x2="0" y2="0"><stop offset="0" stopColor={low} stopOpacity=".75" /><stop offset=".35" stopColor={low} stopOpacity=".3" /><stop offset=".8" stopColor={high} stopOpacity=".18" /><stop offset="1" stopColor={high} stopOpacity="0" /></linearGradient>
      </defs>
      <rect width="1600" height="1000" fill="url(#au-s)" />
      <path d={trails} fill="none" stroke="#dfe8ff" strokeOpacity=".32" strokeWidth="1.4" strokeLinecap="round" />
      {[[520, 70, 1.4, 0.9], [440, 55, -1, 0.6], [370, 40, 1.8, 0.4]].map(([y, a, k, o], i) => <path key={i} d={ribbon(y, a, k)} fill="url(#au-r)" opacity={o} />)}
      <path d="M0 860L180 800L330 836L520 770L700 828L880 790L1080 842L1260 784L1440 820L1600 796V1000H0Z" fill={sky} />
    </svg>
  );
}
const box: CSSProperties = { position: "absolute", inset: 0, width: "100%", height: "100%", display: "block" };

export function Aurora({ sky = "#050a16", low = "#3fd18f", high = "#7a5cff", speed = 1, className, style }: Props) {
  const ref = useRef<HTMLCanvasElement>(null);
  const reduce = useReducedMotion(), fine = useFinePointer();
  const cap = useCapability(true);
  const [failed, setFailed] = useState(false);
  const live = !!cap?.ok && !failed && !reduce;
  useGL(ref, live, { still: reduce, coarse: !fine, onFail: () => setFailed(true) }, (gl) => {
    const prog = program(gl, VS, FS); gl.useProgram(prog);
    const buf = gl.createBuffer(); gl.bindBuffer(gl.ARRAY_BUFFER, buf); gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
    const loc = gl.getAttribLocation(prog, "p"); gl.enableVertexAttribArray(loc); gl.vertexAttribPointer(loc, 2, gl.FLOAT, false, 0, 0);
    const U = (k: string) => gl.getUniformLocation(prog, k);
    gl.uniform3fv(U("a"), rgb(low)); gl.uniform3fv(U("b"), rgb(high)); gl.uniform3fv(U("sky"), rgb(sky));
    return { resize: (w, h) => gl.uniform2f(U("r"), w, h), draw: (t) => { gl.uniform1f(U("t"), t * speed); gl.drawArrays(gl.TRIANGLES, 0, 3); }, dispose: () => { gl.deleteBuffer(buf); gl.deleteProgram(prog); } };
  });
  // poster: the same sky with two soft curtains, painted once by CSS
  const poster = `radial-gradient(120% 38% at 30% 52%, ${low}55, transparent 70%), radial-gradient(90% 30% at 72% 40%, ${high}44, transparent 70%), linear-gradient(to top, ${sky}, ${sky} 40%, #0b1428)`;
  return (
    <span aria-hidden="true" className={className} style={{ position: "absolute", inset: 0, overflow: "hidden", pointerEvents: "none", background: poster, ...style }}>
      {reduce ? <AuroraStill sky={sky} low={low} high={high} /> : live && <canvas ref={ref} style={{ display: "block", width: "100%", height: "100%" }} />}
    </span>
  );
}

"use client";
// Motomation component helpers: the shared motion rules every component in examples/components follows.
// No dependencies beyond React. Each hook cleans up after itself and respects reduced motion.
import { useEffect, useRef, useState, useSyncExternalStore, type RefObject } from "react";

export const clamp = (v: number, lo = 0, hi = 1) => Math.min(hi, Math.max(lo, v));
export const lerp = (a: number, b: number, t: number) => a + (b - a) * t;

const query = (q: string) => (typeof window !== "undefined" && "matchMedia" in window ? window.matchMedia(q) : null);

/** Live media-query state, correct on the first client render: it reads the query while rendering (through
 *  useSyncExternalStore), so a reduced-motion user never gets one animated render before an effect corrects it.
 *  On the server there is no media query: it returns false there, and React re-renders with the real value on hydration. */
export function useMedia(q: string): boolean {
  return useSyncExternalStore(
    (onChange) => { const m = query(q); if (!m) return () => {}; m.addEventListener("change", onChange); return () => m.removeEventListener("change", onChange); },
    () => query(q)?.matches ?? false,
    () => false,
  );
}
/** True when the user asked for reduced motion. Components show their final state instead of animating. */
export const useReducedMotion = () => useMedia("(prefers-reduced-motion: reduce)");
/** True for a mouse or trackpad. Hover and cursor effects run only then. */
export const useFinePointer = () => useMedia("(hover: hover) and (pointer: fine)");
/** Motion is allowed: no reduced-motion preference. */
export const useMotionOK = () => !useReducedMotion();

/** Visibility of an element. With once, it stays true after the first time it enters. */
export function useInView<T extends Element>(ref: RefObject<T | null>, { once = true, margin = "0px 0px -10% 0px", threshold = 0 } = {}): boolean {
  const [seen, setSeen] = useState(false);
  useEffect(() => {
    const el = ref.current; if (!el || typeof IntersectionObserver === "undefined") { setSeen(true); return; }
    const io = new IntersectionObserver(([e]) => { if (e.isIntersecting) { setSeen(true); if (once) io.disconnect(); } else if (!once) setSeen(false); }, { rootMargin: margin, threshold });
    io.observe(el);
    return () => io.disconnect();
  }, [ref, once, margin, threshold]);
  return seen;
}

/**
 * Calls onProgress(0..1) as an element travels through the viewport (0 = its top meets the viewport bottom,
 * 1 = its bottom meets the viewport top). One rAF per frame at most, no React re-renders.
 * Pass enabled=false (for example under reduced motion) to stop listening.
 */
export function useScrollProgress<T extends HTMLElement>(ref: RefObject<T | null>, onProgress: (p: number) => void, enabled = true) {
  const cb = useRef(onProgress); cb.current = onProgress;
  useEffect(() => {
    if (!enabled) return;
    let raf = 0;
    const tick = () => {
      raf = 0; const el = ref.current; if (!el) return;
      const r = el.getBoundingClientRect(); const vh = window.innerHeight;
      cb.current(clamp((vh - r.top) / (r.height + vh)));
    };
    const ask = () => { if (!raf) raf = requestAnimationFrame(tick); };
    tick();
    window.addEventListener("scroll", ask, { passive: true }); window.addEventListener("resize", ask);
    return () => { window.removeEventListener("scroll", ask); window.removeEventListener("resize", ask); cancelAnimationFrame(raf); };
  }, [ref, enabled]);
}

/** Like useScrollProgress for a tall sticky wrapper: 0 when its top reaches the viewport top, 1 when its bottom reaches the viewport bottom. */
export function useStickyProgress<T extends HTMLElement>(ref: RefObject<T | null>, onProgress: (p: number) => void, enabled = true) {
  const cb = useRef(onProgress); cb.current = onProgress;
  useEffect(() => {
    if (!enabled) return;
    let raf = 0;
    const tick = () => { raf = 0; const el = ref.current; if (!el) return; const r = el.getBoundingClientRect(); const run = r.height - window.innerHeight; cb.current(run > 0 ? clamp(-r.top / run) : 0); };
    const ask = () => { if (!raf) raf = requestAnimationFrame(tick); };
    tick();
    window.addEventListener("scroll", ask, { passive: true }); window.addEventListener("resize", ask);
    return () => { window.removeEventListener("scroll", ask); window.removeEventListener("resize", ask); cancelAnimationFrame(raf); };
  }, [ref, enabled]);
}

/** Smoothed scroll velocity in px per frame, delivered every frame while it settles back to 0. */
export function useScrollVelocity(onVelocity: (v: number) => void, enabled = true) {
  const cb = useRef(onVelocity); cb.current = onVelocity;
  useEffect(() => {
    if (!enabled) return;
    let last = window.scrollY, v = 0, raf = 0;
    const loop = () => {
      const y = window.scrollY; v = lerp(v, y - last, 0.2); last = y; cb.current(v);
      raf = Math.abs(v) > 0.05 ? requestAnimationFrame(loop) : 0; if (!raf) cb.current(0);
    };
    const kick = () => { if (!raf) raf = requestAnimationFrame(loop); };
    window.addEventListener("scroll", kick, { passive: true });
    return () => { window.removeEventListener("scroll", kick); cancelAnimationFrame(raf); };
  }, [enabled]);
}

/** A frame loop that pauses when the element is off screen or the tab is hidden. */
export function useFrameLoop<T extends Element>(ref: RefObject<T | null>, frame: (t: number, dt: number) => void, enabled = true) {
  const cb = useRef(frame); cb.current = frame;
  useEffect(() => {
    if (!enabled) return;
    let raf = 0, visible = true, prev = 0;
    const run = (t: number) => { const dt = prev ? Math.min(64, t - prev) : 16; prev = t; cb.current(t, dt); raf = requestAnimationFrame(run); };
    const start = () => { if (!raf && visible && !document.hidden) { prev = 0; raf = requestAnimationFrame(run); } };
    const stop = () => { cancelAnimationFrame(raf); raf = 0; };
    const el = ref.current;
    const io = el && typeof IntersectionObserver !== "undefined" ? new IntersectionObserver(([e]) => { visible = e.isIntersecting; if (visible) start(); else stop(); }) : null;
    if (el && io) io.observe(el);
    const vis = () => (document.hidden ? stop() : start());
    document.addEventListener("visibilitychange", vis); start();
    return () => { stop(); io?.disconnect(); document.removeEventListener("visibilitychange", vis); };
  }, [ref, enabled]);
}

/** Shared timing tokens (motion/tokens.md). UI feedback stays at or under 250ms. */
/** Split text into the units a reader sees as one character (grapheme clusters), for per-letter effects.
 *  `"কালো".split("")` gives 4 code units and a lone vowel sign renders as a dotted circle (◌া); `graphemes("কালো")` gives
 *  ["কা", "লো"]. Emoji ZWJ sequences, flags and combining accents stay whole. Uses Intl.Segmenter, with Array.from (code
 *  points) as the fallback where Segmenter is missing. Cursive scripts (Arabic, Syriac, Thaana, N'Ko, Mongolian…) join each
 *  letter to the next, so a run of them is kept as one unit: split into spans they would lose their joined forms. */
const JOINING = /[\u0600-\u06FF\u0700-\u074F\u0750-\u077F\u0780-\u07BF\u07C0-\u07FF\u0860-\u089F\u08A0-\u08FF\u1800-\u18AF\uFB50-\uFDFF\uFE70-\uFEFF\u200C\u200D]/;
type Seg = { segment(input: string): Iterable<{ segment: string }> };
let seg: Seg | null | undefined;
export function graphemes(text: string): string[] {
  if (seg === undefined) { const S = (Intl as unknown as { Segmenter?: new (l?: string, o?: { granularity: "grapheme" }) => Seg }).Segmenter; seg = S ? new S(undefined, { granularity: "grapheme" }) : null; }
  const units = seg ? Array.from(seg.segment(text), (x) => x.segment) : Array.from(text);
  const out: string[] = [];
  for (const u of units) { const prev = out[out.length - 1]; if (prev !== undefined && JOINING.test(u) && JOINING.test(prev.slice(-1))) out[out.length - 1] = prev + u; else out.push(u); }
  return out;
}

export const EASE = { out: "cubic-bezier(0.22, 1, 0.36, 1)", outStrong: "cubic-bezier(0.16, 1, 0.3, 1)", inOut: "cubic-bezier(0.65, 0, 0.35, 1)", drawer: "cubic-bezier(0.32, 0.72, 0, 1)" } as const;
export const DUR = { press: 120, ui: 180, reveal: 800, stagger: 80 } as const;

"use client";
// Ambient helpers for the heavy backgrounds (Tier 4–5): one capability probe, one WebGL runner, one CSS-animation runner.
// Every heavy background renders its static poster first (same box, so no layout shift), then upgrades only if the
// probe passes and motion is allowed. Both runners pause when the element is off screen or the tab is hidden.
import { useEffect, useState, type RefObject } from "react";

export const MAX_DPR = 1.5;
export type Capability = { ok: boolean; webgl: boolean; reason: string };
let cached: Capability | null = null;

/** Can this device afford a continuously animated background? Cached for the page.
 *  Says no to: Save-Data, ≤ 2 CPU cores, < 4 GB device memory, no WebGL (when needed), and software WebGL renderers
 *  (SwiftShader, llvmpipe), which draw shaders on the CPU. `?ambient=force` in the URL overrides it (testing only). */
export function probeCapability(needWebGL: boolean): Capability {
  if (typeof window === "undefined") return { ok: false, webgl: false, reason: "server" };
  if (/[?&]ambient=force\b/.test(location.search)) return { ok: true, webgl: true, reason: "forced by ?ambient=force" };
  if (!cached) {
    const nav = navigator as Navigator & { connection?: { saveData?: boolean }; deviceMemory?: number };
    let webgl = false, soft = false;
    try {
      const gl = document.createElement("canvas").getContext("webgl");
      if (gl) { webgl = true; const ext = gl.getExtension("WEBGL_debug_renderer_info");
        const name = String(ext ? gl.getParameter(ext.UNMASKED_RENDERER_WEBGL) : gl.getParameter(gl.RENDERER));
        soft = /swiftshader|llvmpipe|software|basic render/i.test(name); gl.getExtension("WEBGL_lose_context")?.loseContext(); }
    } catch { webgl = false; }
    const reason = nav.connection?.saveData ? "save-data" : (nav.hardwareConcurrency || 4) <= 2 ? "2 or fewer CPU cores" : (nav.deviceMemory ?? 8) < 4 ? "under 4 GB memory" : "";
    cached = { ok: !reason, webgl: webgl && !soft, reason: reason || (soft ? "software WebGL" : webgl ? "" : "no WebGL") };
  }
  const c = cached;
  return needWebGL && !c.webgl ? { ok: false, webgl: false, reason: c.reason || "no WebGL" } : c;
}

/** null on the server and first render (poster shows), then the probe result. */
export function useCapability(needWebGL: boolean): Capability | null {
  const [cap, setCap] = useState<Capability | null>(null);
  useEffect(() => setCap(probeCapability(needWebGL)), [needWebGL]);
  return cap;
}

/** Runs while the element is on screen and the tab is visible; calls start() and the cleanup it returns on each change. */
export function useWhileVisible<T extends Element>(ref: RefObject<T | null>, enabled: boolean, start: () => () => void) {
  useEffect(() => {
    const el = ref.current; if (!enabled || !el) return;
    let stop: (() => void) | null = null, onScreen = false;
    const sync = () => { const run = onScreen && !document.hidden; if (run && !stop) stop = start(); else if (!run && stop) { stop(); stop = null; } };
    const io = new IntersectionObserver(([e]) => { onScreen = e.isIntersecting; sync(); }, { rootMargin: "100px" }); io.observe(el);
    document.addEventListener("visibilitychange", sync);
    return () => { io.disconnect(); document.removeEventListener("visibilitychange", sync); stop?.(); };
  }, [ref, enabled]); // eslint-disable-line react-hooks/exhaustive-deps
}

/** CSS-side runner: Web Animations that play while visible and pause (keeping their place) otherwise. */
export function useAmbientAnimations<T extends HTMLElement>(ref: RefObject<T | null>, enabled: boolean, make: (root: T) => Animation[]) {
  useEffect(() => {
    const root = ref.current; if (!enabled || !root) return;
    const anims = make(root); anims.forEach((a) => a.pause());
    let onScreen = false;
    const sync = () => anims.forEach((a) => (onScreen && !document.hidden ? a.play() : a.pause()));
    const io = new IntersectionObserver(([e]) => { onScreen = e.isIntersecting; sync(); }, { rootMargin: "100px" }); io.observe(root);
    document.addEventListener("visibilitychange", sync);
    return () => { io.disconnect(); document.removeEventListener("visibilitychange", sync); anims.forEach((a) => a.cancel()); };
  }, [ref, enabled]); // eslint-disable-line react-hooks/exhaustive-deps
}

export type GLScene = { draw: (t: number) => void; resize?: (w: number, h: number, dpr: number) => void; dispose: () => void };
/** WebGL runner: DPR clamped to MAX_DPR (half on coarse pointers), resizes with the box, pauses off screen / hidden,
 *  draws one still frame under reduced motion, and calls onFail on context loss or a scene that throws. */
export function useGL(ref: RefObject<HTMLCanvasElement | null>, enabled: boolean, opts: { still: boolean; coarse: boolean; onFail: (why: string) => void },
  setup: (gl: WebGLRenderingContext) => GLScene) {
  useEffect(() => {
    const c = ref.current; if (!enabled || !c) return;
    const gl = c.getContext("webgl", { antialias: true, alpha: true, premultipliedAlpha: true }); if (!gl) { opts.onFail("no context"); return; }
    let scene: GLScene; try { scene = setup(gl); } catch (e) { opts.onFail(String(e)); return; }
    const lost = (e: Event) => { e.preventDefault(); opts.onFail("context lost"); }; c.addEventListener("webglcontextlost", lost);
    const dpr = Math.min(MAX_DPR, window.devicePixelRatio || 1) * (opts.coarse ? 0.66 : 1);
    const size = () => { c.width = Math.max(1, Math.round(c.clientWidth * dpr)); c.height = Math.max(1, Math.round(c.clientHeight * dpr)); gl.viewport(0, 0, c.width, c.height); scene.resize?.(c.width, c.height, dpr); if (opts.still) scene.draw(8); };
    size(); const ro = new ResizeObserver(size); ro.observe(c);
    let raf = 0, onScreen = false; const t0 = performance.now();
    const frame = (t: number) => { scene.draw((t - t0) / 1000 + 8); raf = onScreen && !document.hidden ? requestAnimationFrame(frame) : 0; };
    const sync = () => { if (opts.still) return; if (onScreen && !document.hidden && !raf) raf = requestAnimationFrame(frame); };
    const io = new IntersectionObserver(([e]) => { onScreen = e.isIntersecting; sync(); }); io.observe(c);
    document.addEventListener("visibilitychange", sync);
    scene.draw(8);
    return () => { cancelAnimationFrame(raf); ro.disconnect(); io.disconnect(); document.removeEventListener("visibilitychange", sync); c.removeEventListener("webglcontextlost", lost); scene.dispose(); };
  }, [ref, enabled, opts.still, opts.coarse]); // eslint-disable-line react-hooks/exhaustive-deps
}

/** Compile + link a program, throwing with the info log on failure. */
export function program(gl: WebGLRenderingContext, vs: string, fs: string): WebGLProgram {
  const sh = (type: number, src: string) => { const s = gl.createShader(type)!; gl.shaderSource(s, src); gl.compileShader(s);
    if (!gl.getShaderParameter(s, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(s) || "shader"); return s; };
  const p = gl.createProgram()!; gl.attachShader(p, sh(gl.VERTEX_SHADER, vs)); gl.attachShader(p, sh(gl.FRAGMENT_SHADER, fs)); gl.linkProgram(p);
  if (!gl.getProgramParameter(p, gl.LINK_STATUS)) throw new Error(gl.getProgramInfoLog(p) || "link"); return p;
}
export const rgb = (h: string): [number, number, number] => { const n = parseInt(h.replace("#", ""), 16); return [(n >> 16) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255]; };
